DELETE FROM inspection_item_revisions WHERE item_id = '7.5.3.3' AND introduction_type != 'revision';
INSERT INTO inspection_item_revisions (item_id, effective_date, expiry_date, introduction_type, description) VALUES ('7.5.3.3', '2022-03-02', NULL, 'current', '7.5.3.3 수평 개폐식 문 및 접이식 문의 선행 문짝을 열리는 방향으로 가장 취약한 지점에 장비를 사용하지 않고 손으로 150 N의 힘을 가할 때, 7.1에 따른 틈새 6㎜를 초과할 수 있으나 다음 구분에 따른 틈새를 초과할 수 없다.
가) 측면 개폐식 문: 30 ㎜
나) 중앙 개폐식 문: 45 ㎜');
INSERT INTO inspection_item_revisions (item_id, effective_date, expiry_date, introduction_type, description) VALUES ('7.5.3.3', '2013-09-15', '2022-03-01', 'old', '7.2.3.2 수평 개폐식 및 접이식 문의 선행 문짝을 열리는 방향에서 가장 취약한 지점에 장비를 사용하지 않고 손으로 약 150 N의 힘을 가했을 때, 7.1에 규정된 틈새는 6 mm를 초과할 수 있으나 다음에서 규정한 수치는 초과할 수 없다.
가) 측면 개폐식 문 : 30 mm
나) 중앙 개폐식 문 : 45 mm');
INSERT INTO inspection_item_revisions (item_id, effective_date, expiry_date, introduction_type, description) VALUES ('7.5.3.3', '2007-09-10', '2013-09-14', 'old', '4.1.5(1) 승강장 문의 로크 및 스위치의 잠김상태는 카의 문을 닫고 조작장치를 운전상황으로 하여 각층 승강장 문을 연 후 점차 닫히는 위치로 근접시켜 카가 기동할 때의 문과 출입문틀 또는 문과 문의 가장 앞의 테두리와의 거리를 측정하여 다음 기준에 합격하여야 한다.
① 상하개폐문 및 중앙개폐문의 경우에는 5㎝ 이내까지 닫혔을 때 기동하고, 승강장에서는 5㎝ 이상 열려지지 않아야 한다.
② 제1항 이외의 문의 경우에는 2㎝ 이내까지 닫혀졌을 때 기동하고, 승강장에서는 2㎝ 이상 열려지지 않아야 한다. 다만, 화물용(용도) 상승개폐문의 경우 5㎝ 이내까지 닫혀졌을 때 기동하고, 승강장에서는 5㎝ 이상 열려지지 않아야 한다.');
